// Subsetted fonts for the text tool, under the SIL Open Font License 1.1 (see licenses.js):
// Poppins Bold, and "JumpStart Serif" / "JumpStart Mono" (subsets of Liberation Serif Bold and Liberation Mono
// Bold, renamed because "Liberation" is a Reserved Font Name for modified versions).
export const FONT_DATA = {
  sans: "",
  serif: "",
  mono: "",
};
export const FONT_NAMES = { sans: "Rounded sans", serif: "Serif", mono: "Mono" };
export function fontBytes(name) {
  const b64 = FONT_DATA[name] || FONT_DATA.sans;
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out.buffer;
}